def threeSumClosest(nums, target):
    a = sorted(nums)
    n = len(a)
    best = None
    for i in range(n - 2):
        lo, hi = i + 1, n - 1
        while lo < hi:
            s = a[i] + a[lo] + a[hi]
            key = (abs(s - target), s)
            if best is None or key < best:
                best = key
            if s == target:
                return s
            if s < target:
                lo += 1
            else:
                hi -= 1
    return best[1]
